+import 'dart:convert';
+import 'dart:io';
+import 'dart:async';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:finger_desk/app/modules/home/workbench/strategy/strategy_composition.dart';
+import 'package:finger_desk/app/quant/adapters/quant_dataset_repository.dart';
+import 'package:finger_desk/app/quant/fqe/composition_panel.dart';
+import 'package:finger_desk/app/quant/fqe/composition_adapter.dart';
+import 'package:finger_desk/app/quant/fqe/service.dart';
+import 'package:finger_desk/app/quant/fqe/store.dart';
+
+void main() {
+  test(
+      'actual saved dataset freezes twice through the production composition path',
+      () async {
+    final root =
+        await Directory.systemTemp.createTemp('fqe-composition-dataset-');
+    final schema =
+        jsonDecode(File('contracts/quant/v1/schema.json').readAsStringSync())
+            as Map<String, dynamic>;
+    final repository = QuantDatasetRepository(root, schema);
+    final draft = StrategyComposition()..loadExample();
+    try {
+      await repository.initialize();
+      await repository.importFile(
+          'fixtures/quant/cash-application-v1/sample.csv',
+          File('fixtures/quant/cash-application-v1/specification.json')
+              .readAsStringSync());
+      final item = repository.items.single;
+      draft.selectDataset(item['dataset_id'], symbol: 'TEST', timeframe: '1m');
+      final before = draft.semantic();
+      final first = await freezeCompositionHistory(draft, datasets: repository);
+      final second =
+          await freezeCompositionHistory(draft, datasets: repository);
+      expect(first, second);
+      expect(draft.semantic(), before);
+      expect(first['main'], item['dataset_id']);
+      final stream = (first['streams'] as List).single;
+      expect(stream['csv'], contains('TEST'));
+      expect(stream['start_ns'], '1767344460000000000');
+      expect(stream['end_ns'], '1767344640000000000');
+      expect(stream['warmup_bars'], '0');
+      expect(jsonDecode(stream['history_spec'])['instrument']['id'], 'TEST');
+      final snapshots = Directory('${root.path}/runs').listSync();
+      expect(snapshots, hasLength(2),
+          reason:
+              'Every preflight owns an immutable snapshot; none overwrites a prior one');
+      await expectLater(
+          repository.freezeRun(item['dataset_id'], 'composition.invalid'),
+          throwsFormatException);
+      expect(Directory('${root.path}/runs').listSync(), hasLength(2));
+    } finally {
+      await repository.close();
+      draft.dispose();
+      await root.delete(recursive: true);
+    }
+  });
+  test(
+      'real repository freeze reaches native financial oracle without account services',
+      () async {
+    final root = await Directory.systemTemp.createTemp('fqe-dataset-native-');
+    final peer = Platform.environment['FQE_TEST_PEER']!;
+    final pin = jsonDecode(File('ci/fqe-engine.json').readAsStringSync())
+        as Map<String, dynamic>;
+    expect(fqeHash(File(peer).readAsBytesSync()), pin['prepared_sha256']);
+    final service = FqeApplicationService(
+        FqeStore(Directory('${root.path}/fqe')),
+        peer,
+        {...pin, 'executable_sha256': pin['prepared_sha256']});
+    final repository = QuantDatasetRepository(
+        Directory('${root.path}/datasets'),
+        jsonDecode(File('contracts/quant/v1/schema.json').readAsStringSync()));
+    final original = StrategyComposition()..loadExample();
+    final state = original.toJson();
+    original.dispose();
+    for (final n in state['nodes'] as List) {
+      if (n['kind'] == 'ema') n['kind'] = 'sma';
+    }
+    final draft = StrategyComposition.restore(state)
+      ..configure('initialCash', '100.00')
+      ..configure('feeBps', '0')
+      ..configure('slippageBps', '0')
+      ..editParameter('fast_period', 'value', '2')
+      ..editParameter('slow_period', 'value', '3')
+      ..updateNode('entry', 'cashCap', '10.00');
+    try {
+      await service.initialize();
+      final hs = jsonDecode(
+          File('test/quant/fixtures/fqe-composition/history-spec.json')
+              .readAsStringSync());
+      final instrument = hs['instrument'];
+      final spec = {
+        'instrument': {
+          'instrument_id': instrument['id'],
+          'quote_currency': instrument['currency'],
+          for (final k in [
+            'price_step',
+            'quantity_step',
+            'money_step',
+            'minimum_quantity',
+            'minimum_notional'
+          ])
+            k: instrument[k],
+          'timezone': 'UTC',
+          'calendar_id': 'csv-utc-sessions-v1'
+        },
+        'timeframe': '1m',
+        'source': 'public.synthetic.repository-to-native.v1',
+        'adjustment': 'raw-no-actions',
+        'volume_unit': 'base_quantity',
+        'acquired_at': hs['acquired_at'],
+        'performance_start': hs['performance_start'],
+        'calendar_version': 1,
+        'sessions': hs['calendar']['sessions']
+      };
+      await repository.importFile(
+          'test/quant/fixtures/fqe-composition/history.csv', jsonEncode(spec));
+      draft.selectDataset(repository.items.single['dataset_id'],
+          symbol: 'DEMO', timeframe: '1m');
+      final history =
+          await freezeCompositionHistory(draft, datasets: repository);
+      final prepared = await prepareFqeComposition(service, draft, history);
+      await prepared.start(service, 'repository oracle');
+      final timer = Stopwatch()..start();
+      while (service.busy) {
+        if (timer.elapsed > const Duration(seconds: 20))
+          throw TimeoutException('native repository run');
+        await Future<void>.delayed(const Duration(milliseconds: 10));
+      }
+      expect(service.failure, isNull);
+      expect(service.report!['fills'].map((f) => f['price']).toList(),
+          ['4.00', '2.00']);
+      expect(service.report!['metrics']['final_equity'], '98.00');
+      expect(service.current!['project']['project_id'], draft.projectId);
+      expect(service.history.where((r) => r['error'] != null), isEmpty);
+    } finally {
+      await service.shutdown();
+      await repository.close();
+      draft.dispose();
+      await root.delete(recursive: true);
+    }
+  },
+      skip: Platform.environment['FQE_TEST_PEER'] == null
+          ? 'Set FQE_TEST_PEER to the pinned prepared native helper'
+          : false);
+}
